Literal.Value:
'{
  "data": {
    "name": "dataset"
  },
  "width": "container",
  "height": "container",
  "transform": [
    {
      "filter": "datum[''Não realizada (GWh)''] > 0"
    },
    {
      "window": [
        {
          "op": "row_number",
          "as": "pos"
        },
        {
          "op": "sum",
          "field": "Não realizada (GWh)",
          "as": "acum"
        }
      ],
      "sort": [
        {
          "field": "Não realizada (GWh)",
          "order": "descending"
        }
      ]
    },
    {
      "joinaggregate": [
        {
          "op": "sum",
          "field": "Não realizada (GWh)",
          "as": "tot"
        }
      ]
    },
    {
      "calculate": "datum.acum / datum.tot",
      "as": "pct_acum"
    },
    {
      "calculate": "datum.pct_acum - datum[''Não realizada (GWh)''] / datum.tot < 0.8",
      "as": "no80"
    },
    {
      "filter": "datum.pos <= 25"
    }
  ],
  "layer": [
    {
      "mark": {
        "type": "bar",
        "width": {
          "band": 0.75
        }
      },
      "encoding": {
        "x": {
          "field": "Ponto de conexão",
          "type": "nominal",
          "sort": {
            "field": "pos",
            "op": "min"
          },
          "title": null,
          "axis": {
            "labelAngle": -40,
            "labelLimit": 120,
            "labelFontSize": 9
          }
        },
        "y": {
          "field": "Não realizada (GWh)",
          "type": "quantitative",
          "title": "GWh cortados",
          "axis": {
            "format": ",.0f",
            "tickCount": 4
          }
        },
        "color": {
          "field": "no80",
          "type": "nominal",
          "scale": {
            "domain": [
              true,
              false
            ],
            "range": [
              "#F2C811",
              "#C8C6C4"
            ]
          },
          "legend": null
        },
        "tooltip": [
          {
            "field": "pos",
            "title": "Posição"
          },
          {
            "field": "Ponto de conexão"
          },
          {
            "field": "Não realizada (GWh)",
            "title": "GWh",
            "format": ",.0f"
          },
          {
            "field": "pct_acum",
            "title": "% acumulado",
            "format": ".0%"
          }
        ],
        "opacity": {
          "condition": {
            "test": "datum.__selected__ == ''off''",
            "value": 0.25
          },
          "value": 1
        }
      }
    },
    {
      "layer": [
        {
          "mark": {
            "type": "line",
            "color": "#191919",
            "strokeWidth": 2,
            "point": {
              "color": "#191919",
              "size": 16
            }
          },
          "encoding": {
            "x": {
              "field": "Ponto de conexão",
              "type": "nominal",
              "sort": {
                "field": "pos",
                "op": "min"
              },
              "title": null,
              "axis": {
                "labelAngle": -40,
                "labelLimit": 120,
                "labelFontSize": 9
              }
            },
            "y": {
              "field": "pct_acum",
              "type": "quantitative",
              "title": "% acumulado",
              "scale": {
                "domain": [
                  0,
                  1
                ]
              },
              "axis": {
                "format": ".0%",
                "orient": "right",
                "grid": false,
                "tickCount": 5
              }
            }
          }
        },
        {
          "mark": {
            "type": "rule",
            "color": "#C84720",
            "strokeDash": [
              4,
              3
            ]
          },
          "encoding": {
            "y": {
              "datum": 0.8,
              "type": "quantitative"
            }
          }
        }
      ]
    }
  ],
  "resolve": {
    "scale": {
      "y": "independent"
    }
  }
}'
